            )?;
            self.conn.last_insert_rowid()
        }
    };

    let project = ProjectId(id);
    if self.reprojected.insert(id) {
        projection::bootstrap(canonical)?;
        self.reproject_all(canonical, project)?;
    }
    Ok(project)
}

