1	//! `panopt agent-config` - emit a Claude Code `--mcp-config` JSON for a
2	//! hand-launched agent.
3	//!
4	//! Bridges the gap between cockpit-spawned agents (which get a stable id and
5	//! identity via the env-templated config at `mcp.rs`) and agents started
6	//! manually with `claude --mcp-config ...`. Without this, a hand-launched
7	//! agent falls back to the rotating MCP session id and shows up in the
8	//! registry as a ghost that other agents cannot pin down (DESIGN.md §9).
9	//!
10	//! Emits a stdio config so Claude Code spawns `panopt _mcp-proxy`, which
11	//! holds the long-lived MCP session and forwards to panoptd over HTTP -
12	//! making the hand-launched session survive panoptd restarts transparently,
13	//! the same way cockpit-spawned ones do.
14	
15	use std::path::PathBuf;
16	
17	use anyhow::{Context, Result};
18	use serde_json::json;
19	
20	use crate::paths;
21	
22	/// Emit the `--mcp-config` JSON to stdout.
23	///
24	/// `token`, when supplied, replaces the usual read of
25	/// `~/.local/share/panopt/token`. This is the seam that lets an agent host
26	/// on another machine emit a config without first scp'ing the daemon
27	/// host's token file into place: paste the value from `panopt token` on
28	/// the daemon host directly.
29	pub fn run(
30	    host: Option<String>,
31	    port: u16,
32	    id: Option<String>,
33	    name: Option<String>,
34	    token: Option<String>,
35	    ws: Option<PathBuf>,
36	) -> Result<()> {
37	    let host = host.unwrap_or_else(|| "127.0.0.1".into());
38	    let id = id.unwrap_or_else(default_id);
39	    let name = name.unwrap_or_else(|| id.clone());
40	    let ws = resolve_ws(ws)?;
41	    let token = match token {
42	        Some(t) => t,
43	        None => panopt_core::auth::read_token(&paths::token()?).context(
44	            "reading the panopt token (pass --token <value>, or start the daemon with \
45	             `panopt up`)",
46	        )?,
47	    };
48	    // Bake in this binary's absolute path so the spawned proxy is the same
49	    // panopt the user invoked, regardless of what `claude`'s PATH looks like
50	    // when it executes the stdio child. Falls back to bare `panopt` only if
51	    // the OS refuses to tell us our own path - in which case PATH lookup is
52	    // the best we can do.
53	    let panopt_bin = std::env::current_exe()
54	        .ok()
55	        .map(|p| p.to_string_lossy().into_owned())
56	        .unwrap_or_else(|| "panopt".to_string());
57	
58	    let cfg = json!({
59	        "mcpServers": {
60	            "panopt": {
61	                "type": "stdio",
62	                "command": panopt_bin,
63	                "args": [
64	                    "--port", port.to_string(),
65	                    "_mcp-proxy",
66	                    "--host", host,
