#[test]
fn ensure_project_by_identity_adopts_unifies_and_resists_clobber() {
    let (mut store, _db) = store();
    let a = tempfile::tempdir().unwrap();

    // A path-keyed connect seeds the row with identity == canonical path.
    let p_path = store.ensure_project(a.path()).unwrap();
    assert_eq!(
        identity_of(&store, p_path),
        std::fs::canonicalize(a.path())
            .unwrap()
            .to_string_lossy()
    );

    // The edge resolver connects with a repo identity for the same path:
    // it adopts the existing row (no UNIQUE(root) collision) and re-keys it.
    let p_id = store.ensure_project_by_identity("repo-key", a.path()).unwrap();
    assert_eq!(p_path, p_id, "identity connect adopts the path-keyed row");
    assert_eq!(identity_of(&store, p_id), "repo-key");

    // A second checkout at a different path but the same identity unifies
    // onto the same project row - the whole point of repo identity.
    let b = tempfile::tempdir().unwrap();
    let p_other = store.ensure_project_by_identity("repo-key", b.path()).unwrap();
    assert_eq!(p_id, p_other, "same identity unifies distinct checkouts");

    // A later path-only client (the CLI) must NOT clobber the established
    // repo identity back to the path.
    let p_path2 = store.ensure_project(a.path()).unwrap();
    assert_eq!(p_id, p_path2);
    assert_eq!(identity_of(&store, p_id), "repo-key", "path call left identity intact");
}

