/// Run the stdio<->HTTP proxy until the client closes stdin.
///
/// `host`/`port` locate the daemon; `ws` is the project's projection path;
/// `project` is its opaque identity key (derived from `ws` when not given);
/// `id`/`name` declare the agent identity; `token` authenticates. All but
/// `token` arrive as CLI args from the MCP config; `token` is read from the
/// shared token file.
pub fn run(
    host: &str,
    port: u16,
    ws: &str,
    project: Option<&str>,
    id: &str,
    name: &str,
    token: Option<&str>,
) -> Result<()> {
    let token = match token {
        Some(t) => t.to_string(),
        None => panopt_core::auth::read_token(&paths::token())
            .context("reading the panopt bearer token")?,
    };
    // Resolve the project identity here, at the edge: an explicit `--project`
    // wins, otherwise derive it from the workspace (committed id -> remote ->
    // root commit -> path; see `project_identity`). Resolving in the proxy means
    // every spawned agent - cockpit-templated or hand-launched - sends a stable
    // repo identity to the daemon, and the daemon never needs git. An empty
    // `--project` (an unset `${PANOPT_PROJECT}` in the cockpit template) falls
    // through to derivation rather than poisoning the key.
    let project = project
        .filter(|p| !p.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| crate::project_identity::resolve(std::path::Path::new(ws)).key);
    let base = format!("http://{host}:{port}/mcp");
    let url = build_url(&base, ws, &project, id, name);
    proxy_loop(&url, &token)
}

