1	//! The `agent` and `_agent` subcommands.
2	
3	use std::fmt::Write as _;
4	use std::io::Read as _;
5	use std::os::unix::process::CommandExt;
6	use std::path::PathBuf;
7	use std::process::Command;
8	
9	use anyhow::{bail, Context, Result};
10	use percent_encoding::{utf8_percent_encode, NON_ALPHANUMERIC};
11	use serde_json::json;
12	
13	use crate::mcpclient::Client;
14	use crate::{mcp, paths};
15	
16	// Note: `_agent` no longer pre-registers against the daemon directly. The
17	// stdio MCP proxy that Claude Code spawns from this pane (via the config at
18	// `mcp.rs`) initializes its panoptd session as soon as Claude Code sends
19	// its first `initialize` over stdio, which both registers the agent and
20	// applies its name to the registry entry. The pane-death hook keeps using
21	// `_agent-leave` over HTTP because at that point the agent process is gone
22	// and there is no proxy to call through.
23	
24	/// `panopt agent [name]` - open a new agent pane in the running cockpit.
25	///
26	/// The cockpit's Zellij plugin is the spawner; this just sends it a
27	/// `panopt:spawn-agent` pipe message. Must be run inside the cockpit session.
28	pub fn spawn(name: Option<String>) -> Result<()> {
29	    if std::env::var_os("ZELLIJ").is_none() {
30	        bail!("`panopt agent` runs inside the cockpit - start one with `panopt up`");
31	    }
32	
33	    let mut cmd = Command::new("zellij");
34	    cmd.arg("pipe").arg("--name").arg("panopt:spawn-agent");
35	    if let Some(name) = name {
36	        // Mint the id here - a native process has the system RNG. The plugin
37	        // relays the payload straight to `panopt _agent --id`.
38	        cmd.arg("--").arg(mint_id(Some(&name)));
39	    }
40	    let status = cmd
41	        .status()
42	        .context("running `zellij pipe` (is zellij installed and on PATH?)")?;
43	    if !status.success() {
44	        bail!("`zellij pipe` failed");
45	    }
46	    println!("requested a new agent pane");
47	    Ok(())
48	}
49	
50	/// `panopt _agent` - the entrypoint that runs inside an agent pane.
51	///
52	/// Sets the per-agent environment and replaces this process with `claude`, so
53	/// the pane *is* the agent with no PANopt wrapper around it. The MCP template
54	/// at `mcp.rs` tells claude to spawn `panopt _mcp-proxy` as a stdio MCP
55	/// server, which carries the env vars set here into the panoptd URL and
56	/// keeps the session alive across daemon restarts.
57	pub fn exec_in_pane(ws: Option<PathBuf>, id: Option<String>, port: u16) -> Result<()> {
58	    let config = mcp::ensure()?;
59	    let ws = resolve_ws(ws)?;
60	    let id = id.unwrap_or_else(|| mint_id(None));
61	    let token_path = paths::token()?;
62	    let token = panopt_core::auth::read_token(&token_path)
63	        .with_context(|| format!("reading panopt token from {}", token_path.display()))?;
64	    let host = std::env::var("PANOPT_HOST").unwrap_or_else(|_| "127.0.0.1".into());
65	    // The proxy is *this* binary - bake its absolute path into the env so
66	    // the MCP config template (`${PANOPT_BIN}`) expands to the same panopt
67	    // the user invoked, independent of whatever PATH claude inherits.
68	    let panopt_bin =
69	        std::env::current_exe().context("looking up panopt's own path for the MCP config")?;
70	
71	    // `exec` replaces this process image, so it returns only on failure.
72	    let err = Command::new("claude")
73	        .arg("--mcp-config")
74	        .arg(&config)
75	        .env("PANOPT_BIN", &panopt_bin)
76	        .env("PANOPT_WS", &ws)
77	        .env("PANOPT_AGENT", &id)
78	        .env("PANOPT_NAME", &id)
79	        .env("PANOPT_PORT", port.to_string())
80	        .env("PANOPT_HOST", &host)
81	        .env("PANOPT_TOKEN", &token)
82	        .exec();
83	    Err(err).context("could not exec `claude` (is it installed and on PATH?)")
84	}
85	
86	/// `panopt _agent-leave --id <id>` - tell the daemon that the agent named by
87	/// `id` has gone away, so its registry entry and locks clear immediately.
88	///
89	/// Used by the sidebar plugin's pane-death hook: when a cockpit-spawned agent
90	/// pane closes, the plugin runs this command to call the daemon's
91	/// `agent_leave` MCP tool on behalf of the dead pane. Without it, a closed
92	/// cockpit-spawned agent (which uses a stable `?agent=<id>` key) would
93	/// linger in the registry indefinitely because declared identities never
94	/// idle-prune.
95	///
96	/// Connects with `?agent=<id>` so the daemon sees this as a request *from*
97	/// that agent, and `agent_leave` removes the entry and releases its locks.
98	/// Best-effort: missing daemon or missing agent are no-ops the caller logs
99	/// but does not surface.
100	pub fn leave(ws: Option<PathBuf>, id: String, port: u16) -> Result<()> {
101	    let ws = resolve_ws(ws)?;
102	    let token = panopt_core::auth::read_token(&paths::token()?)
103	        .context("reading the panopt token (start the daemon with `panopt up`)")?;
104	    let encode = |s: &str| utf8_percent_encode(s, NON_ALPHANUMERIC).to_string();
105	    let url = format!(
106	        "http://127.0.0.1:{port}/mcp?ws={}&agent={}&token={}",
107	        encode(&ws.to_string_lossy()),
108	        encode(&id),
109	        encode(&token),
110	    );
111	    let client = Client::connect(&url).context("connecting to the panopt daemon")?;
112	    let result = client.call("agent_leave", json!({}));
113	    client.close();
114	    result.map(|_| ())
115	}
116	
117	/// The project root: the given path, or the current directory, canonicalized.
118	fn resolve_ws(ws: Option<PathBuf>) -> Result<PathBuf> {
119	    let ws = match ws {
120	        Some(ws) => ws,
121	        None => std::env::current_dir().context("reading the current directory")?,
122	    };
123	    std::fs::canonicalize(&ws).with_context(|| format!("no such directory: {}", ws.display()))
124	}
125	
126	/// Mint a stable agent id. With a name: `<name>-<4 hex>` - readable and unique.
127	/// Without: `agent-<8 hex>`.
128	fn mint_id(name: Option<&str>) -> String {
129	    match name {
130	        Some(name) => format!("{name}-{}", hex(2)),
131	        None => format!("agent-{}", hex(4)),
132	    }
133	}
134	
135	/// `n` random bytes from the system RNG, lowercase hex.
136	fn hex(n: usize) -> String {
137	    let mut bytes = vec![0u8; n];
138	    std::fs::File::open("/dev/urandom")
139	        .and_then(|mut f| f.read_exact(&mut bytes))
