        );
        assert!(
            ignoring_rule(dir.path()).is_none(),
            "id should be committable after repair"
        );
        // And `git add` accepts it without -f.
        assert!(git_ok(dir.path(), &["add", "--dry-run", ".panopt/project-id"]));
        let _ = id;
    }
}
